We recall the results from the proof sketch: We have
\begin{align*}
\operatorname{KL}(p^*(\bm{Y}^T)\|\widehat p_B(\bm{Y}^T))\le\sum_{t=1}^T\mathbb{E}_{\bm{Y}^{t-1}, \mathcal{B}_t}\operatorname{KL}(p^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|\widehat p_B(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})).
\end{align*}
We first construct another auxiliary distribution
\begin{align}\label{eq:def_nu}
\widetilde\nu(\mathbf{x}_{\mathcal{B}}|\mathbf{y})\propto q^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y})\exp(h_{\bm{\theta}, B}(\mathbf{x}_{\mathcal{B}}, \mathbf{y})),
\end{align}
which swaps the proposal distribution of $\widehat p_B$. By Lemma~\ref{lemma:swap_proposal} and Lemma~\ref{lemma:proposal_remove_B}, we have
\begin{align*}
&\operatorname{KL}(p^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|\widehat p_B(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1}))\\
&\le\underbrace{2\operatorname{KL}(p^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|\widetilde\nu(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1}))}_{I_1}+\underbrace{\log\{1+e^{4B}\chi^2(q^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|q_{\bm{\theta}}(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1}))\}}_{I_2}.
\end{align*}
For the term $I_2$, we have
\begin{align*}
I_2&\le e^{4B}\log\{1+\chi^2(q^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|q_{\bm{\theta}}(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1}))\}\\
&\le e^{4B}\sum_{i\in\mathcal{B}_t}\chi^2(p_i^*(x_i|\bm{Y}^{t-1})\|p_{\bm{\theta}, i}(x_i|\bm{Y}^{t-1})),
\end{align*}
where the first inequality holds due to Lemma~\ref{lemma:get_C_from_log}, and the second inequality holds due to Lemma~\ref{lemma:chi2_error}.

Taking the expectation over all possible batches $\mathcal{B}_t$, we have
\begin{align*}
\mathbb{E}_{\mathcal{B}_t|\bm{Y}^{t-1}}[I_2]\le e^{4B}n_t\cdot\sum_{i\in\mathcal{M}(\bm{Y}^{t-1})}\mathbb{P}\{i\in\mathcal{B}_t|\bm{Y}^{t-1}\}\cdot\chi^2(p_i^*(x_i|\bm{Y}^{t-1})\|p_{\bm{\theta}, i}(x_i|\bm{Y}^{t-1})).
\end{align*}
For the term $I_1$, we use Lemma~\ref{lemma:swap_tilt} with $\mu=p_B^*$, $\widetilde\mu=\widetilde\nu$, $g=h_{\bm{\theta}, B}-h_B^*$, and $\nu=p^*$. Since $|h_{\bm{\theta}, B}-h_B^*|\le2B$, we have
\begin{align*}
I_1&\le8e^{2B}\operatorname{KL}(p^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|p_B^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1}))\\
&\quad+8e^{2B}\mathbb{E}_{\bm{X}_{\mathcal{B}_t}\sim p_B^*(\cdot|\bm{Y}^{t-1})}[(h_{\bm{\theta}, B}(\bm{X}_{\mathcal{B}_t}, \bm{Y}^{t-1})-h_B^*(\bm{X}_{\mathcal{B}_t}, \bm{Y}^{t-1}))^2]\\
&\le8e^{2B}\operatorname{KL}(p^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|p_B^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1}))\\
&\quad+24e^{2B}\mathbb{E}_{\bm{X}_{\mathcal{B}_t}\sim p^*(\cdot|\bm{Y}^{t-1})}[(h_{\bm{\theta}, B}(\bm{X}_{\mathcal{B}_t}, \bm{Y}^{t-1})-h_B^*(\bm{X}_{\mathcal{B}_t}, \bm{Y}^{t-1}))^2]\\
&\quad+128B^2e^{2B}D_{\mathrm{H}}^2(p^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|p_B^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1}))\\
&\le e^{2B}(8+64B^2)\operatorname{KL}(p^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1})\|p_B^*(\bm{X}_{\mathcal{B}_t}|\bm{Y}^{t-1}))\\
&\quad+24e^{2B}\mathbb{E}_{\bm{X}_{\mathcal{B}_t}\sim p^*(\cdot|\bm{Y}^{t-1})}[(h_{\bm{\theta}, B}(\bm{X}_{\mathcal{B}_t}, \bm{Y}^{t-1})-h_B^*(\bm{X}_{\mathcal{B}_t}, \bm{Y}^{t-1}))^2],
\end{align*}
where the second inequality holds due to Lemma~\ref{lemma:hellinger} with $h=\frac{(h^*-h_B^*)^2}{4B^2}$, and the last inequality holds because $D_{\mathrm{H}}^2(\cdot, \cdot)\le\frac12\operatorname{KL}(\cdot, \cdot)$. The KL-divergence term, which is the clipping error, can be bounded by Lemma~\ref{lemma:clipping}. The squared-error term is analyzed in Lemma~\ref{lemma:squared_error}.
Combining all the above, we complete the proof of Theorem~\ref{theorem:main}.

The error decomposition is the same as that in Theorem~\ref{theorem:main}. We then consider the three terms separately.

\noindent\textbf{Clipping.} The new definition of $h_B^*$ only affects the characterization of $h^*-h_B^*$, which is
\begin{align*}
h^*-h_B^*&=\mathbb{E}_{k}\mathbb{E}_{\widetilde\mathcal{B}:|\widetilde\mathcal{B}|=k-1}\bigg[\bigg(\frac{n_t}{n_t-k+1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\log\frac{p_{i}^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{y})}-B\bigg)_+\\
&-\bigg(\frac{-n_t}{n_t-k+1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\log\frac{p_{i}^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{y})}-B\bigg)_+\bigg].
\end{align*}
We thus have
\begin{align*}
(h^*-h_B^*)_+&\le\mathbb{E}_{k}\mathbb{E}_{\widetilde\mathcal{B}:|\widetilde\mathcal{B}|=k-1}\bigg[\bigg(\frac{n_t}{n_t-k+1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\log\frac{p_{i}^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{y})}-B\bigg)_+\bigg];\\
(h_B^*-h^*)_+&\le\mathbb{E}_{k}\mathbb{E}_{\widetilde\mathcal{B}:|\widetilde\mathcal{B}|=k-1}\bigg[\bigg(\frac{-n_t}{n_t-k+1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\log\frac{p_{i}^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{y})}-B\bigg)_+\bigg].
\end{align*}

\noindent\textbf{Proposal.} The proposal probability is irrelevant to the Rao-Blackwellized increment, so the bound for $\mathcal{E}_{\mathrm{Proposal}}$ is the same.

\noindent\textbf{Acceptance probability.}
It suffices to re-derive Lemma~\ref{lemma:squared_error}:
\begin{align*}
&|h_{\bm{\theta}, B}(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})|^2\\
&=\bigg|\mathbb{E}_k\mathbb{E}_{\widetilde\mathcal{B}\subseteq\mathcal{B}:|\widetilde\mathcal{B}|=k-1}\\
&\quad\bigg[\operatorname{clip}_B\bigg(\frac{n_t}{n_t-k+1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_{\bm{\theta}, i}(x_i|\mathbf{y})}\bigg)-\operatorname{clip}_B\bigg(\frac{n_t}{n_t-k+1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\log\frac{p_i^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{y})}\bigg)\bigg]\bigg|^2\\
&\le\mathbb{E}_k\mathbb{E}_{\widetilde\mathcal{B}\subseteq\mathcal{B}:|\widetilde\mathcal{B}|=k-1}\bigg|\frac{n_t}{n_t-k+1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\bigg(\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}-\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{y})}{p_i^*(x_i|\mathbf{y})}\bigg)\bigg|^2\\
&\le\mathbb{E}_{k\ge2}\mathbb{E}_{\widetilde\mathcal{B}\subseteq\mathcal{B}:|\widetilde\mathcal{B}|=k-1}\bigg[\frac{2n_t^2}{n_t-k+1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\bigg(\bigg|\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}\bigg|^2+\bigg|\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{y})}{p_i^*(x_i|\mathbf{y})}\bigg|^2\bigg)\bigg]\\
&=\sum_{k=2}^{n_t}\frac{2}{\binom{n_t-1}{k-1}}\sum_{\substack{\widetilde\mathcal{B}\subseteq\mathcal{B}\\|\widetilde\mathcal{B}|=k-1}}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\bigg|\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}\bigg|^2+2n_t\sum_{i\in\mathcal{B}}\bigg|\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{y})}{p_i^*(x_i|\mathbf{y})}\bigg|^2,
\end{align*}
where the first inequality holds due to Jensen's inequality and the $1$-Lipschitzness of the clip function, and the second inequality holds due to Cauchy-Schwarz inequality. Therefore, the bound of $|h_{\bm{\theta}, B}(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})|^2$ is the same as that in Lemma~\ref{lemma:squared_error}, so the analysis and results are the same.

The KL-divergence of $p^*$ and $p_B^*$ satisfies
\begin{align}
&\operatorname{KL}(p^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y})\|p_B^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y}))\nonumber\\
&=\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim p^*(\cdot|\mathbf{y})}\bigg[\log\{q^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y})\exp(h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))\}-\log\frac{q^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y})\exp(h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))}{\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim q^*(\cdot|\mathbf{y})}\exp(h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))}\bigg]\nonumber\\
&=\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim p^*(\cdot|\mathbf{y})}[h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})]+\log\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim q^*(\cdot|\mathbf{y})}\exp(h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))\nonumber\\
&\le\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim p^*(\cdot|\mathbf{y})}[h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})]+\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim q^*(\cdot|\mathbf{y})}[\exp(h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))-\exp(h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))]\nonumber\\
&=\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim p^*(\cdot|\mathbf{y})}[h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})+\exp(h^*_B(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))-1]\label{eq:upper_clipping}\\
&=\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim q^*(\cdot|\mathbf{y})}[e^{h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})}(h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))+e^{h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})}-e^{h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})}],\label{eq:lower_clipping}
\end{align}
where the inequality holds because $\log z\le z-1$ and $\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim q^*(\cdot|\mathbf{y})}\exp(h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))=1$.

\noindent\textbf{Upper clipping:} $h^*>h^*_B$. We use \eqref{eq:upper_clipping} and the property $e^{z}\le1+z+z^2/2$ ($z<0$), and we have
\begin{align*}
h^*-h_B^*+e^{h_B^*-h^*}-1\le(h^*-h_B^*)^2/2.
\end{align*}
\noindent\textbf{Lower clipping:} $h^*<h_B^*$. We use \eqref{eq:lower_clipping} and $1-(1+z)e^{-z}\le z^2/2$ for $z\ge0$, and we have
\begin{align*}
e^{h^*}(h^*-h_B^*)+e^{h_B^*}-e^{h^*}=e^{h_B^*}[e^{h^*-h_B^*}(h^*-h_B^*)+1-e^{h^*-h_B^*}]\le e^{h_B^*}\min\{1, (h_B^*-h^*)^2/2\}.
\end{align*}
Therefore,
\begin{align*}
&\operatorname{KL}(p^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y})\|p_B^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y}))\\
&\le\frac12\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim p^*(\cdot|\mathbf{y})}[(h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))_+^2]\\
&\quad+\mathbb{E}_{\mathbf{x}_\mathcal{B}\sim q^*(\cdot|\mathbf{y})}[e^{h_B^*}\min\{1, (h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))_-^2/2\}].
\end{align*}
Note that
\begin{align*}
h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})=\mathbb{E}_{\pi, k}\bigg[\bigg(n_t\log\frac{p_{i_k}^*(x_{i_k}|\mathbf{z}_{k-1})}{p_{i_k}^*(x_{i_k}|\mathbf{y})}-B\bigg)_++\bigg(n_t\log\frac{p_{i_k}^*(x_{i_k}|\mathbf{z}_{k-1})}{p_{i_k}^*(x_{i_k}|\mathbf{y})}+B\bigg)_-\bigg],
\end{align*}
so we have
\begin{align*}
(h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))_+&\le\mathbb{E}_{\pi, k}\bigg[\bigg(n_t\log\frac{p_{i_k}^*(x_{i_k}|\mathbf{z}_{k-1})}{p_{i_k}^*(x_{i_k}|\mathbf{y})}-B\bigg)_+\bigg],\\
(h^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y}))_-&\ge\mathbb{E}_{\pi, k}\bigg[\bigg(n_t\log\frac{p_{i_k}^*(x_{i_k}|\mathbf{z}_{k-1})}{p_{i_k}^*(x_{i_k}|\mathbf{y})}+B\bigg)_-\bigg].
\end{align*}

By direct calculation, we have
\begin{align*}
&1+\chi^2(q^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y})\|q_{\bm{\theta}}(\mathbf{x}_{\mathcal{B}}|\mathbf{y}))=\sum_{\mathbf{x}_{\mathcal{B}}}\frac{q^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y})^2}{q_{\bm{\theta}}(\mathbf{x}_{\mathcal{B}}|\mathbf{y})}=\sum_{\mathbf{x}_{\mathcal{B}}}\prod_{i\in\mathcal{B}}\frac{p_i^*(x_i|\mathbf{y})^2}{p_{\bm{\theta}, i}(x_i|\mathbf{y})}=\prod_{i\in\mathcal{B}}\sum_{x_i}\frac{p_i^*(x_i|\mathbf{y})^2}{p_{\bm{\theta}, i}(x_i|\mathbf{y})}\\
&=\prod_{i\in\mathcal{B}}(1+\chi^2(p_i^*\|p_{\bm{\theta}, i})).
\end{align*}
Taking the logarithm, we have
\begin{align*}
\log\{1+\chi^2(q^*(\mathbf{x}_{\mathcal{B}}|\mathbf{y})\|q_{\bm{\theta}}(\mathbf{x}_{\mathcal{B}}|\mathbf{y}))\}=\sum_{i\in\mathcal{B}}\log\{1+\chi^2(p_i^*\|p_{\bm{\theta}, i})\}\le\sum_{i\in\mathcal{B}}\chi^2(p_i^*\|p_{\bm{\theta}, i}),
\end{align*}
where the inequality holds because $\log(1+z)\le z$.

We first trivially have $(h_{\bm{\theta}, B}-h_B^*)^2\le4B^2$. Additionally, we have
\begin{align*}
&|h_{\bm{\theta}, B}(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})|^2\\
&=\bigg|\mathbb{E}_{\pi, k}\bigg[\operatorname{clip}_B\bigg(n_t\log\frac{p_{\bm{\theta}, i_k}(x_{i_k}|\mathbf{z}_{k-1})}{p_{\bm{\theta}, i_k}(x_{i_k}|\mathbf{y})}\bigg)-\operatorname{clip}_B\bigg(n_t\log\frac{p_{i_k}^*(x_{i_k}|\mathbf{z}_{k-1})}{p_{i_k}^*(x_{i_k}|\mathbf{y})}\bigg)\bigg]\bigg|^2\\
&\le\mathbb{E}_{\pi, k}\bigg|\operatorname{clip}_B\bigg(n_t\log\frac{p_{\bm{\theta}, i_k}(x_{i_k}|\mathbf{z}_{k-1})}{p_{\bm{\theta}, i_k}(x_{i_k}|\mathbf{y})}\bigg)-\operatorname{clip}_B\bigg(n_t\log\frac{p_{i_k}^*(x_{i_k}|\mathbf{z}_{k-1})}{p_{i_k}^*(x_{i_k}|\mathbf{y})}\bigg)\bigg|^2\\
&\le n_t^2\mathbb{E}_{\pi, k}\bigg|\log\frac{p_{\bm{\theta}, i_k}(x_{i_k}|\mathbf{z}_{k-1})}{p_{\bm{\theta}, i_k}(x_{i_k}|\mathbf{y})}-\log\frac{p_{i_k}^*(x_{i_k}|\mathbf{z}_{k-1})}{p_{i_k}^*(x_{i_k}|\mathbf{y})}\bigg|^2\\
&\le2n_t^2\mathbb{E}_{\pi, k\ge2}\bigg[\bigg|\log\frac{p_{\bm{\theta}, i_k}(x_{i_k}|\mathbf{z}_{k-1})}{p_{i_k}^*(x_{i_k}|\mathbf{z}_{k-1})}\bigg|^2+\bigg|\log\frac{p_{\bm{\theta}, i_k}(x_{i_k}|\mathbf{y})}{p_{i_k}^*(x_{i_k}|\mathbf{y})}\bigg|^2\bigg]\\
&=\sum_{k=2}^{n_t}\frac{2}{\binom{n_t-1}{k-1}}\sum_{\widetilde\mathcal{B}\subset\mathcal{B}, |\widetilde\mathcal{B}|=k-1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\bigg|\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}{p_i^*(x_i|\mathbf{x}_{\widetilde\mathcal{B}}\oplus\mathbf{y})}\bigg|^2+2n_t\sum_{i\in\mathcal{B}}\bigg|\log\frac{p_{\bm{\theta}, i}(x_i|\mathbf{y})}{p_i^*(x_i|\mathbf{y})}\bigg|^2,
\end{align*}
where the first inequality holds due to Jensen's inequality, the second inequality holds because the  $\operatorname{clip}$ function is $1$-Lipschitz, and the third inequality holds due to Cauchy-Schwarz inequality. Taking the expectation over $\mathbf{x}_{\mathcal{B}}$, we have
\begin{align*}
\mathbb{E}_{\mathbf{x}_{\mathcal{B}}\sim p^*(\cdot|\mathbf{y})}|h_{\bm{\theta}, B}(\mathbf{x}_{\mathcal{B}}, \mathbf{y})-h_B^*(\mathbf{x}_{\mathcal{B}}, \mathbf{y})|^2\le\sum_{k=2}^{n_t}\frac{2}{\binom{n_t-1}{k-1}}\sum_{\widetilde\mathcal{B}\subset\mathcal{B}, |\widetilde\mathcal{B}|=k-1}\sum_{i\in\mathcal{B}\backslash\widetilde\mathcal{B}}\epsilon_{i, \widetilde\mathcal{B}}(\mathbf{y})^2+2n_t\sum_{i\in\mathcal{B}}\epsilon_i(\mathbf{y})^2.
\end{align*}

Fix $C\ge1$. Define
\begin{align*}
f(t)=\log(1+Ct)-C\log(1+t).
\end{align*}
Then
\begin{align*}
f(0)=0,\quad f'(t)=\frac{C}{1+Ct}-\frac{C}{1+t}=\frac{-C(C-1)t}{(1+t)(1+Ct)}\le0.
\end{align*}
Therefore, $f(t)\le0$ for all $t\ge0$.
